tasks.command:
cd '/out/jobs/ci-yml-visual-baseline-update'; set -a; if [ -f '/out/jobs/ci-yml-visual-baseline-update.env' ]; then . '/out/jobs/ci-yml-visual-baseline-update.env'; fi; set +a; node <<'NODE'
const fs = require('fs');
const pages = ['home', 'preise', 'dimensionierung', 'foerderung', 'prozess', 'ratgeber', 'kontakt', 'anfrage'];
const expected = new Set(pages.flatMap((page) => ['dark', 'light'].map((theme) => `${page}-${theme}.png`)));
const entries = fs.readdirSync('baseline/visual', { withFileTypes: true });
const actual = entries.filter((entry) => entry.name !== '.gitkeep');
const valid = actual.length === 16 && actual.every((entry) => entry.isFile() && expected.has(entry.name));
const keep = entries.find((entry) => entry.name === '.gitkeep');
if (!valid || (keep && !keep.isFile())) {
  console.error('Grundlinie ungültig: genau 16 erwartete PNG und ausschließlich optional .gitkeep sind erlaubt.');
  process.exit(1);
}
console.log('Grundlinie geprüft: 16 PNG (8 Seiten × 2 Themen), keine fremden Einträge.');
NODE
